@dataclasses.dataclass
class ConversationConfig:
    # An opaque, user-specified string representing the human agent who handled the conversation.
    agent_id: Any = None
    # Call-specific metadata.
    call_metadata: Any = None
    # Info for correlating across conversations.
    correlation_info: Any = None
    # Output only. The time at which the conversation was created.
    create_time: Any = None
    # The conversation source, which is a combination of transcript and audio.
    data_source: Any = None
    # Output only. All the matched Dialogflow intents in the call. The key corresponds to a Dialogflow intent, format: projects/{project}/agent/{agent}/intents/{intent}
    dialogflow_intents: Any = None
    # Output only. The duration of the conversation.
    duration: Any = None
    # The time at which this conversation should expire. After this time, the conversation data and any associated analyses will be deleted.
    expire_time: Any = None
    # A map for the user to specify any custom fields. A maximum of 100 labels per conversation is allowed, with a maximum of 256 characters per entry.
    labels: Any = None
    # A user-specified language code for the conversation.
    language_code: Any = None
    # The analysis resource.
    latest_analysis: Any = None
    # Conversation summarization suggestion data.
    latest_summary: Any = None
    # Immutable. The conversation medium.
    medium: Any = None
    # Optional. JSON metadata encoded as a string. This field is primarily used by Insights integrations with various telephony systems and must be in one of Insight's supported formats.
    metadata_json: Any = None
    # Immutable. The resource name of the conversation. Format: projects/{project}/locations/{location}/conversations/{conversation}
    name: Any = None
    # Obfuscated user ID which the customer sent to us.
    obfuscated_user_id: Any = None
    # Conversation metadata related to quality management.
    quality_metadata: Any = None
    # Output only. The annotations that were generated during the customer and agent interaction.
    runtime_annotations: Any = None
    # The time at which the conversation started.
    start_time: Any = None
    # A message representing the transcript of a conversation.
    transcript: Any = None
    # Input only. The TTL for this resource. If specified, then this TTL will be used to calculate the expire time.
    ttl: Any = None
    # Output only. The number of turns in the conversation.
    turn_count: Any = None
    # Output only. The most recent time at which the conversation was updated.
    update_time: Any = None

